  "claim": {
    "component_id": "C026.component",
    "value": "Missing trace spans represent unknown phase durations and must not be treated as zero-duration phases.",
    "scope": "Interpretation of absent phase telemetry.",
    "provenance": {
      "refs": [
        {
          "source_id": "P023",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P023 directly supplies the distinction between unknown and zero-duration phases."
    }
  },
  "signal_basis": {
    "component_id": "C026.signal_basis",
    "value": "Phase-duration measurement encounters missing trace spans, leaving the corresponding durations unobserved.",
    "scope": "Missing phase telemetry in the proposed concurrency-step investigation, assuming it occurs; the packet reports no completed observations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P023",
          "role": "SUPPORT"
        },
        {
          "source_id": "P025",
          "role": "CONTEXT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P018 identifies phase-duration measurement, P023 identifies missing spans and their interpretation, and P025 establishes that the measurements are proposed."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C026.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported interpretation of missing telemetry."
    }
  },
  "rationale": "An absent trace span supplies no measurement of elapsed phase time. Treating it as zero would assert a duration unsupported by the telemetry. Retaining it as unknown is licensed within the claim's stated scope.",
  "uncertainty": "The actual durations and reasons for missing spans remain unknown; neither is needed to justify preserving missing values as unknown.",
  "anomalies": []
}
